flow.set("gis_db_ready", true);
flow.set("gis_db_error", "");
msg.params = { $group: flow.get("webgis_group") };
delete msg._client;
return msg;

const group=flow.get("webgis_group");
const p=msg.payload||{};
const client=msg._client;
const reply=(payload)=>{const out=Array(12).fill(null);out[4]={payload,_client:client};return out;};
const fail=(message)=>reply({action:"operation_result",success:false,request_id:p.request_id||"",message});
const uid=String(p.uid||"").trim().toUpperCase();
const uidValid=/^(?:[0-9A-F]{8}|[0-9A-F]{14}|[0-9A-F]{20})$/.test(uid);
let sessions=flow.get("gis_admin_sessions")||{};
const now=Date.now();
for(const key of Object.keys(sessions))if(sessions[key].expires<=now)delete sessions[key];
const socket=client?.socketId;
if(client && p.action==="admin_login"){
  const username=env.get("WEBGIS_ADMIN_USER")||"admin";
  const password=env.get("WEBGIS_ADMIN_PASSWORD")||"admin123";
  if(!socket||p.username!==username||p.password!==password)return reply({action:"login_result",success:false,message:"Username atau password salah"});
  const token=now.toString(36)+"-"+Math.random().toString(36).slice(2)+Math.random().toString(36).slice(2);
  sessions[token]={socket,expires:now+1800000};flow.set("gis_admin_sessions",sessions);
  return reply({action:"login_result",success:true,token,message:"Login berhasil"});
}
const authorized=()=>{
  const token=String(p.token||"");
  if(!socket||!token||!sessions[token]||sessions[token].socket!==socket)return false;
  sessions[token].expires=now+1800000;flow.set("gis_admin_sessions",sessions);return true;
};
if(client && p.action==="admin_logout"){
  if(authorized()){delete sessions[String(p.token)];flow.set("gis_admin_sessions",sessions);}
  return reply({action:"logout_result"});
}
if(msg._kind==="mqtt_status"){
 flow.set("gis_mqtt",msg.status?.fill==="green");
 return reply({action:"connection",sqlite:!!flow.get("gis_db_ready"),ready:!!flow.get("gis_db_ready"),mqtt:!!flow.get("gis_mqtt"),group_id:group,error:flow.get("gis_db_error")||""});
}
if(client && p.action==="get_state"){
 if(!flow.get("gis_db_ready"))return reply({action:"connection",sqlite:false,ready:false,mqtt:!!flow.get("gis_mqtt"),group_id:group,error:flow.get("gis_db_error")||""});
 msg.params={$group:group};return [msg];
}
const adminActions=["register","admin_users","admin_history","admin_update","admin_delete","admin_toggle"];
if(client && adminActions.includes(p.action) && !authorized())return reply({action:"session_expired",message:"Sesi admin berakhir. Silakan login kembali."});
if(!flow.get("gis_db_ready"))return client?fail("Database belum siap."):null;
if(client && p.action==="admin_users"){
 msg.params={$group:group};msg._op="admin_users";return [null,null,null,null,null,null,null,msg];
}
if(client && p.action==="admin_history"){
 msg.params={$group:group};msg._op="admin_history";return [null,null,null,null,null,null,null,null,msg];
}
if(client && p.action==="get_profile"){
 if(!uidValid)return fail("UID tidak valid");
 msg.params={$group:group,$uid:uid};return [null,msg];
}
const validateProfile=()=>{
 const name=String(p.name||"").trim();const photo=String(p.photo||"");
 if(!name||name.length>100)return "Nama wajib diisi, maksimal 100 karakter.";
 if(typeof p.latitude!=="number"||typeof p.longitude!=="number"||
   !Number.isFinite(p.latitude)||!Number.isFinite(p.longitude)||
   Math.abs(p.latitude)>90||Math.abs(p.longitude)>180)return "Koordinat tidak valid.";
 if(photo&&(!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(photo)||
    Buffer.byteLength(photo,"utf8")>210000))return "Foto tidak valid atau terlalu besar.";
 return "";
};
if(client && p.action==="register"){
 if(!uidValid)return fail("UID harus 8, 14, atau 20 karakter heksadesimal.");
 const error=validateProfile();if(error)return fail(error);
 msg._request={uid,request_id:p.request_id||"",group};msg._op="register";
 msg.params={$group:group,$uid:uid,$name:p.name.trim(),$photo:p.photo||"",$lat:p.latitude,$lng:p.longitude,$now:now};
 return [null,null,msg];
}
if(client && p.action==="admin_update"){
 if(!uidValid)return fail("UID tidak valid.");const error=validateProfile();if(error)return fail(error);
 if(!["IDLE","CHECK_IN","CHECK_OUT"].includes(p.status))return fail("Status tidak valid.");
 msg._request={uid,request_id:p.request_id||"",group};msg._op="admin_update";
 msg.params={$group:group,$uid:uid,$name:p.name.trim(),$photo:p.photo||"",$lat:p.latitude,$lng:p.longitude,$status:p.status,$now:now};
 const out=Array(12).fill(null);out[9]=msg;return out;
}
if(client && (p.action==="admin_delete"||p.action==="admin_toggle")){
 if(!uidValid)return fail("UID tidak valid.");
 if(p.action==="admin_toggle"&&typeof p.enabled!=="boolean")return fail("Status UID tidak valid.");
 msg._request={uid,request_id:p.request_id||"",group};msg._op=p.action;
 msg.params=p.action==="admin_toggle"
  ? {$group:group,$uid:uid,$enabled:p.enabled?1:0}
  : {$group:group,$uid:uid};
 const out=Array(12).fill(null);out[p.action==="admin_delete"?10:11]=msg;return out;
}
if(msg._kind!=="scan"||msg.retain)return null;
if(p.group_id!==group)return null;
if(!uidValid)return null;
const mode=String(p.mode||"SCAN").toUpperCase();
if(mode==="REGISTER"){const out=reply({action:"registration_uid",uid});if(p.event_id&&p.node_id)out[6]={payload:{node_id:p.node_id,event_id:p.event_id,type:"scan",result:"RECEIVED"}};return out;}
if(mode!=="SCAN")return null;
const nodeId=String(p.node_id||"mqttx"),eventId=String(p.event_id||msg._msgid||"");
if(!/^[A-Za-z0-9_-]{1,64}$/.test(nodeId)||!eventId||eventId.length>160)return null;
msg._request={uid,group,node_id:nodeId,event_id:eventId};msg._op="scan";
msg.params={$group:group,$uid:uid,$event:eventId,$node:nodeId,$now:now};
return [null,null,null,msg];

const group = flow.get("webgis_group");
flow.set("gis_db_ready", true);
flow.set("gis_db_error", "");
const connection = {
  _client: msg._client,
  payload: {
    action: "connection",
    sqlite: true,
    ready: true,
    mqtt: !!flow.get("gis_mqtt"),
    group_id: group,
    error: "",
  },
};
const snapshot = {
  _client: msg._client,
  payload: {
    action: "snapshot",
    group_id: group,
    items: Array.isArray(msg.payload) ? msg.payload : [],
  },
};
return [msg._client || msg._op === "init" ? [connection, snapshot] : snapshot];

return {
  _client: msg._client,
  payload: {
    action: "profile",
    uid: msg._request.uid,
    profile: msg.payload[0] || null,
  },
};

const success = Array.isArray(msg.payload) && msg.payload.length > 0;
const reply = {
  _client: msg._client,
  payload: {
    action: "operation_result",
    request_id: msg._request.request_id,
    operation: "register",
    success,
    message: success
      ? "Pendaftaran berhasil. Marker baru berstatus IDLE."
      : "UID sudah terdaftar. Gunakan kartu lain.",
  },
};
return [reply, success ? { params: { $group: msg._request.group } } : null];

const row = msg.payload?.[0],
  e = msg._request;
if (!row) {
  msg.params = { $group: e.group, $uid: e.uid, $event: e.event_id };
  return [msg, null, null, null];
}
const ui = {
  payload: {
    action: "scan_result",
    success: true,
    uid: e.uid,
    name: row.name,
    status: row.status,
    timestamp: row.scanned_at,
    message: row.status === "CHECK_IN" ? "Check-in berhasil" : "Check-out berhasil",
  },
};
return [null, ui, { params: { $group: e.group } },
  { payload: { node_id:e.node_id, event_id:e.event_id, type:"scan", result:"OK", state:row.status } }];

const r = msg.payload?.[0] || {},
  e = msg._request;
const result = r.event_uid
  ? r.event_uid === e.uid
    ? "DUPLICATE"
    : "EVENT_ID_CONFLICT"
  : !r.registered_uid || r.deleted
    ? "UNKNOWN_UID"
    : !r.enabled ? "INACTIVE_UID" : "COOLDOWN";
const ui = (result === "UNKNOWN_UID" || result === "INACTIVE_UID") ? {
  payload: { action: "scan_result", success: false, uid: result === "UNKNOWN_UID" ? "UID unknown" : e.uid,
    message: result === "INACTIVE_UID" ? "UID sedang dinonaktifkan" : "UID belum terdaftar" }
} : null;
return [ui, { payload: { node_id:e.node_id, event_id:e.event_id, type:"scan", result } }];

function respond() {
const text = msg.error?.message || "Operasi SQLite gagal";
node.warn(text);
if (msg._op === "init") {
  flow.set("gis_db_ready", false);
  flow.set("gis_db_error", text);
  return [
    {
      payload: {
        action: "connection",
        sqlite: false,
        ready: false,
        mqtt: !!flow.get("gis_mqtt"),
        group_id: flow.get("webgis_group"),
        error: "SQLite gagal: " + text,
      },
    },
    null,
  ];
}
if (msg._client)
  return [
    {
      _client: msg._client,
      payload: {
        action: "operation_result",
        request_id: msg._request?.request_id || "",
        success: false,
        message: "Operasi SQLite gagal. Periksa Debug.",
      },
    },
    null,
  ];
return [{ payload: { action: "scan_result", success: false,
  uid: msg._request?.uid || "", message: "Operasi SQLite gagal. Periksa Debug." } }, null];

}
const result = respond();
const e = msg._request;
const ack = msg._op === "scan" && e?.node_id && e?.event_id
  ? { payload: { node_id:e.node_id, event_id:e.event_id, type:"scan", result:"ERROR" } } : null;
return [result ? result[0] : null, ack];

const group = flow.get("webgis_group");
let devices = context.get("devices") || {};
const now = Date.now();
let p = msg.payload;
let ack = null;
if (msg.topic?.startsWith("webgis/")) {
  if (msg.retain) return null;
  try { if (Buffer.isBuffer(p)) p = p.toString(); if (typeof p === "string") p = JSON.parse(p); }
  catch (_) { return null; }
  if (!p || typeof p !== "object" || Array.isArray(p)) return null;
  const id = String(p.node_id || "");
  if (!/^[A-Za-z0-9_-]{1,40}$/.test(id) || p.group_id !== group ||
      msg.topic !== `webgis/${group}/node/${id}/status` ||
      !["SCAN", "REGISTER"].includes(p.mode) || p.status !== "ONLINE") return null;
  if (!devices[id] && Object.keys(devices).length >= 32) return null;
  devices[id] = { node_id: id, mode: p.mode, reader_ready: p.reader_ready === true,
    rssi: Number.isFinite(p.rssi) ? p.rssi : null, last_seen: now };
  ack = { payload: { node_id:id, type:"status", result:"RECEIVED", mode:p.mode } };
}
const nodes = Object.values(devices);
context.set("devices", devices);
const payload = { action: "device_status", nodes };
const requested = p?.action === "get_state";
const signature = JSON.stringify(nodes);
if (signature === context.get("last") && !requested) return [null, ack];
context.set("last", signature);
return [{ payload, ...(requested ? { _client: msg._client } : {}) }, ack];

const group = "kelompok-00";
flow.set("webgis_group", group);
return [
  { action: "subscribe", topic: `webgis/${group}/rfid/scan` },
  { action: "subscribe", topic: `webgis/${group}/node/+/status` }
];

const group = flow.get("webgis_group");
const p = msg.payload || {};
const nodeId = String(p.node_id || "");
if (!group || !/^[A-Za-z0-9_-]{1,40}$/.test(nodeId) ||
    !["status", "scan"].includes(p.type)) return null;
const ack = { group_id: group, node_id: nodeId, type: p.type,
  result: String(p.result || "ERROR") };
if (p.type === "status") ack.mode = p.mode;
if (p.type === "scan") {
  ack.event_id = String(p.event_id || "");
  if (!ack.event_id) return null;
  if (p.state) ack.state = p.state;
}
return { topic: `webgis/${group}/node/${nodeId}/ack`,
  payload: JSON.stringify(ack), qos: "1", retain: false };

const op=msg._op,rows=Array.isArray(msg.payload)?msg.payload:[];
if(op==="admin_users")return [{payload:{action:"admin_users",users:rows},_client:msg._client},null];
if(op==="admin_history")return [{payload:{action:"admin_history",history:rows},_client:msg._client},null];
const success=rows.length>0;
const names={admin_update:"Data pengguna diperbarui.",admin_delete:"Pengguna diarsipkan; riwayat scan tersimpan.",admin_toggle:"Status UID diperbarui."};
const response={payload:{action:"operation_result",operation:op,request_id:msg._request?.request_id||"",success,
 message:success?names[op]:"UID tidak ditemukan atau sudah diarsipkan."},_client:msg._client};
return [response,success?{params:{$group:msg._request.group}}:null];
